// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));

        uint256 receiverBefore = receiver.balance;
        uint256 ownerBefore = address(this).balance;

        // Ensure owner has enough balance
        vm.deal(address(this), amount);

        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        if (!success) {
            assertTrue(receiver.balance == receiverBefore);
        } else {
            assertTrue(receiver.balance == receiverBefore + amount);
        }
    }
}

