pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        amount = bound(amount, 0, address(this).balance);
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(this));

        address owner = address(this); // owner is msg.sender in constructor
        uint256 ownerBefore = owner.balance;
        uint256 receiverBefore = receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool ruleHolds = owner.balance == ownerBefore - (reverted ? 0 : amount);
        assertTrue(ruleHolds);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0) && receiver != address(c) && receiver != address(this));
        amount = bound(amount, 0, address(c).balance);

        address payable owner = payable(address(this));
        uint256 initialOwnerBalance = owner.balance;
        uint256 initialReceiverBalance = payable(receiver).balance;
        uint256 initialContractBalance = address(c).balance;

        vm.deal(address(c), initialContractBalance + amount);
        c.sendTo(receiver, amount);

        uint256 finalOwnerBalance = owner.balance;
        uint256 finalReceiverBalance = payable(receiver).balance;
        uint256 finalContractBalance = address(c).balance;

        assertTrue(
            initialOwnerBalance + initialReceiverBalance + initialContractBalance ==
            finalOwnerBalance + finalReceiverBalance + finalContractBalance
        );
    }
}

