pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(address(c).balance >= amount);
        uint256 balanceBefore = address(c).balance;
        c.sendTo(receiver, amount);
        assertTrue(address(c).balance <= balanceBefore);
    }
}
